        await this.$storex.projects.chatWihProject(chat)
      } catch (err) {
        console.error('[QuickChat] postAndSend error:', err)
        this.$ui?.addNotification?.({
          text: 'Failed to send message',
          type: 'error'
        })
      } finally {
        this.waiting = false
      }
